'use strict';
const D=window.MutiaraData,C=window.MutiaraCore,esc=C.escapeHtml;
const main=document.querySelector('main');
const formatDate=s=>new Date(s.length===10?s+'T12:00:00+08:00':s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kuala_Lumpur'});
const formatTime=s=>new Date(s).toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kuala_Lumpur'})+' MYT';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const title=(e,h,p)=>`<p class="eyebrow">${e}</p><h1>${h}</h1><p class="sub">${p}</p>`;
const options=(items,first)=>`<option value="">${first}</option>`+items.map(v=>`<option>${esc(v)}</option>`).join('');
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const noticeState={query:'',area:'',type:'',phase:'all',date:'2026-11-05',sort:'newest'};
let feedbackDraft=null;
const phase=(n,date=today())=>n.end<date?'Archived':n.start>date?'Upcoming':'Active';
function loadCases(){try{return C.read(localStorage)}catch{return{records:[],error:'Browser storage is unavailable. You can explore sample cases, but new feedback cannot be saved.'}}}
function persist(rows){try{C.save(localStorage,rows);return true}catch{return false}}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,4500)}
function noticeCard(n,date=today()){return`<article class="notice"><div class="notice-top">${badge(n.type,n.type==='Road closure'?'closure':'notice')}${badge(phase(n,date))}<span class="impact ${n.severity.toLowerCase()}">${n.severity} impact</span></div><h3>${esc(n.title)}</h3><div class="meta">${esc(n.area)} · ${formatDate(n.start)} – ${formatDate(n.end)}</div><p>${esc(n.summary)}</p><a class="text-link" href="#updates/${n.id}">View notice & access information →</a></article>`}
const train=`<svg viewBox="0 0 420 280" role="img" aria-label="Illustration of a light rail train on an elevated track"><g fill="none" stroke="#74937b" opacity=".35"><path d="M5 205h410M60 205v-82h27v82m20 0V86h35v119m16 0v-57h30v57m150 0v-106h30v106m10 0V65h23v140"/><circle cx="270" cy="99" r="80"/></g><path d="M5 232 415 158v16L5 249z" fill="#89aa83"/><path d="m59 237 2 43h15v-46m244-44v90h15V187" fill="#628a70"/><path d="m47 153 239-43q37-4 50 24l13 28-296 53z" fill="#e5ecd9"/><path d="m56 161 226-41q27-5 37 18L61 185z" fill="#214e43"/><path d="m59 193 283-51 6 14-286 51z" fill="#c2d789"/><path d="m272 122 3 43m-63-32 4 43m-63-32 5 43m-64-32 4 43" stroke="#edf1e3" stroke-width="5"/><text x="247" y="230" fill="#c3d6b8" font-size="10" letter-spacing="3">MOVING PENANG FORWARD</text></svg>`;
function home(){
  const count=loadCases().records.length;
  main.innerHTML=title('CONNECTED COMMUNITIES. BETTER JOURNEYS.','Your neighbourhood. Your next chapter.','Stay informed, plan ahead and make your voice heard as Penang moves forward.')+`<section class="hero"><div class="hero-copy"><p class="eyebrow">PENANG LRT · MUTIARA LINE</p><h2 class="hero-title">A more connected future starts with you.</h2><p>Your community hub for construction information, local access updates and a direct channel for feedback.</p><a class="button" href="#updates">Explore construction updates &nbsp; ↗</a></div><div class="hero-art">${train}</div></section><div class="grid"><a class="card stat" href="#updates"><span class="icon">▤</span><div><strong>${String(D.notices.length).padStart(2,'0')}</strong><small>Demonstration notices →</small></div></a><a class="card stat" href="#map"><span class="icon">◇</span><div><strong>04</strong><small>Illustrative work zones →</small></div></a><a class="card stat" href="#tracking"><span class="icon">◎</span><div><strong>${String(count).padStart(2,'0')}</strong><small>Your locally saved concerns →</small></div></a></div><div class="section-head"><h2>In your neighbourhood</h2><a class="text-link" href="#updates">View all updates →</a></div><div class="two"><div class="card">${D.notices.slice(0,2).map(n=>noticeCard(n)).join('')}</div><div><div class="callout"><span class="icon">✎</span><h2 style="margin-top:18px">Let’s build it together.</h2><p>Have a concern about construction, local access or your neighbourhood? Tell us what’s happening.</p><a href="#feedback" class="button">Share your feedback ↗</a></div><div class="card" style="margin-top:18px"><h3>Already submitted a complaint?</h3><p class="sub" style="font-size:12px">Follow its progress with your reference number.</p><a class="text-link" href="#tracking">Track your complaint →</a></div></div></div><div class="section-head"><h2>One portal. Five ways to stay connected.</h2></div><div class="module-links"><a href="#home"><b>01</b><span>Understand the project<small>Purpose, people & community needs</small></span>↗</a><a href="#updates"><b>02</b><span>Plan around works<small>Schedules, restrictions & access</small></span>↗</a><a href="#map"><b>03</b><span>Explore your area<small>Work zones & local impacts</small></span>↗</a><a href="#feedback"><b>04</b><span>Raise a concern<small>Clear form & reference receipt</small></span>↗</a><a href="#tracking"><b>05</b><span>Follow the response<small>Status history & follow-up notes</small></span>↗</a></div><section id="project"><div class="section-head"><h2>The project, and the people around it</h2></div><div class="card"><p>The Mutiara Line is a planned light rail connection linking key destinations on Penang Island and the mainland. This community platform explores how residents and project teams can communicate during construction.</p><p class="classification">APPLICATION CATEGORY <b>Community information portal & feedback management application</b></p><div class="project-facts"><div><b>Stay informed</b><p>Find work schedules, access arrangements and local disruption notices.</p></div><div><b>Plan your journey</b><p>Explore affected areas and read pedestrian and business access information.</p></div><div><b>Be heard</b><p>Record a concern, keep its reference and follow a clear response timeline.</p></div></div><a class="text-link" href="https://laluanmutiara.mymrt.com.my/lrt-mutiara-line/" target="_blank" rel="noopener noreferrer">Official MRT Corp project information ↗</a><p class="meta">Project overview source checked 2 Nov 2026. The sample notices on this website are independently created scenarios.</p></div></section><div class="section-head"><h2>Designed for our community</h2></div><div class="grid"><div class="card"><span class="icon">⌂</span><h3>Residents & commuters</h3><p class="muted">Understand nearby works and report noise, dust or pedestrian safety concerns.</p><a class="text-link" href="#map">Explore local impacts →</a></div><div class="card"><span class="icon">▧</span><h3>Local businesses</h3><p class="muted">Find premises access information and raise delivery or customer access issues.</p><a class="text-link" href="#updates">Read access notices →</a></div><div class="card"><span class="icon">♧</span><h3>Project teams & authorities</h3><p class="muted">A proposed shared channel for publishing notices and responding to community concerns.</p><a class="text-link" href="#tracking/MC-2026-DEMO01">Explore response workflow →</a></div></div><div class="section-head"><h2>A few helpful answers</h2></div><div class="card faq"><details><summary>Is this the official LRT website?</summary><p>No. Mutiara Connect is a CMT322 academic simulation. For official information, use the MRT Corp project link above.</p></details><details><summary>Does someone receive my feedback?</summary><p>No. Part A stores feedback in this browser only. No email is sent and no authority receives your submission. Use fictional details during demonstrations.</p></details><details><summary>How does complaint tracking work?</summary><p>Submit a concern to receive a reference. On the tracking page, enter that reference or open one of your locally saved records. A labelled demonstration control lets you simulate the response stages.</p></details><details><summary>Can I use the map for travelling?</summary><p>The map uses real OpenStreetMap streets and geography. Area markers and linked construction notices are demonstration data, not verified work boundaries or an official LRT route.</p></details></div>`;
}
function updates(id){
  if(id){const n=D.notices.find(n=>n.id===id);if(!n){notFound('Notice not found','This notice does not exist.','#updates','Browse all notices');return}main.innerHTML=`<a class="back-link" href="#updates">← All construction updates</a>`+title('DEMONSTRATION NOTICE',esc(n.title),'Sample community information · '+esc(n.id))+`<div class="two"><article class="card"><div class="notice-top">${badge(n.type,n.type==='Road closure'?'closure':'notice')}${badge(phase(n,noticeState.date))}<span class="impact ${n.severity.toLowerCase()}">${n.severity} impact</span></div><p>${esc(n.details)}</p><dl class="facts"><div><dt>Area</dt><dd>${esc(n.area)}</dd></div><div><dt>Work dates</dt><dd>${formatDate(n.start)} – ${formatDate(n.end)}</dd></div><div><dt>Hours</dt><dd>${esc(n.hours)}</dd></div><div><dt>Published</dt><dd>${formatDate(n.published)}</dd></div></dl><p class="meta">Status shown for sample assessment date ${formatDate(noticeState.date)}.</p><h3>Traffic & diversion</h3><p>${esc(n.diversion)}</p><h3>Pedestrian access</h3><p>${esc(n.pedestrian)}</p><h3>Business & premises access</h3><p>${esc(n.access)}</p><div class="info">This notice is a fictional academic scenario. Check official information and signs on site before travelling.</div></article><div><div class="callout"><h2>Know the area</h2><p>View this neighbourhood on the construction map.</p><a class="button" href="#map/${n.zone}">View work zone →</a></div><div class="card" style="margin-top:18px"><h3>Affected by these works?</h3><p class="muted">Record an access or construction concern.</p><a class="text-link" href="#feedback/${n.zone}">Share feedback about this area →</a></div></div></div>`;return}
  main.innerHTML=title('PLAN AHEAD','Construction updates','Find work schedules, road restrictions and access arrangements by neighbourhood.')+`<div class="info">Demonstration data only. Dates are sample scenarios; this is not a live construction feed.</div><div class="filters"><input id="notice-search" type="search" aria-label="Search notices" placeholder="Search notices or locations…"><select id="notice-area" aria-label="Filter by area">${options(D.areas,'All areas')}</select><select id="notice-type" aria-label="Filter notice type">${options([...new Set(D.notices.map(n=>n.type))],'All notice types')}</select><select id="notice-phase" aria-label="Filter notice status"><option value="all">All statuses</option><option value="active">Active</option><option value="upcoming">Upcoming</option><option value="archived">Archived</option></select><button class="secondary" id="reset-filters">Reset filters</button></div><div class="schedule-controls"><div><label for="schedule-date">Assess sample work status on</label><input type="date" id="schedule-date" required value="2026-11-05"></div><div><label for="notice-sort">Sort notices</label><select id="notice-sort"><option value="newest">Latest published</option><option value="start">Work start date</option><option value="impact">Highest impact</option></select></div><p class="meta">A fixed sample date makes this demonstration repeatable. Change it to explore upcoming, active and archived work.</p></div><p class="meta" id="result-count" role="status"></p><div class="card" id="notice-results"></div>`;
  const fields={'notice-search':'query','notice-area':'area','notice-type':'type','notice-phase':'phase','schedule-date':'date','notice-sort':'sort'};
  Object.entries(fields).forEach(([id,key])=>document.getElementById(id).value=noticeState[key]);
  const filter=()=>{Object.entries(fields).forEach(([id,key])=>noticeState[key]=document.getElementById(id).value);if(!noticeState.date){document.querySelector('#schedule-date').setCustomValidity('Choose a date to assess the work schedule.');document.querySelector('#schedule-date').reportValidity();return}document.querySelector('#schedule-date').setCustomValidity('');let list=C.filterNotices(D.notices,noticeState);list=C.sortNotices(list,noticeState.sort);document.querySelector('#result-count').textContent=`${list.length} notice${list.length===1?'':'s'} found · Status assessed on ${formatDate(noticeState.date)}`;document.querySelector('#notice-results').innerHTML=list.length?list.map(n=>noticeCard(n,noticeState.date)).join(''):'<div class="empty"><h3>No matching notices</h3><p>Try another search term, area or notice type, or reset the filters.</p></div>'};
  Object.keys(fields).forEach(id=>document.getElementById(id).addEventListener(id==='notice-search'?'input':'change',filter));document.querySelector('#reset-filters').onclick=()=>{Object.assign(noticeState,{query:'',area:'',type:'',phase:'all',date:'2026-11-05',sort:'newest'});Object.entries(fields).forEach(([id,key])=>document.getElementById(id).value=noticeState[key]);filter()};filter();
}
let activeMap=null;
function map(id){
  const selected=D.zones.find(z=>z.id===id)||D.zones[0];
  main.innerHTML=title('EXPLORE YOUR NEIGHBOURHOOD','Construction map','Explore Penang on a real street map and select an area for local notices.')+`<div class="info">Real map: OpenStreetMap streets and geography. The coloured markers are approximate neighbourhood centres with fictional demonstration notices, not verified construction sites or an official LRT alignment.</div><div class="map-toolbar"><label for="impact-filter">Show work zones</label><select id="impact-filter"><option value="">All impact levels</option><option>Low</option><option>Moderate</option><option>High</option></select><span id="zone-count" role="status" class="meta">4 zones shown</span><span class="map-legend"><i class="low"></i>Low <i class="moderate"></i>Moderate <i class="high"></i>High</span></div><div class="map-layout"><div><div id="real-map" class="real-map" aria-label="Real street map of Penang"><iframe id="map-fallback" title="OpenStreetMap street map of Penang" src="https://www.openstreetmap.org/export/embed.html?bbox=100.22%2C5.26%2C100.39%2C5.45&layer=mapnik" referrerpolicy="strict-origin-when-cross-origin"></iframe><div id="map-canvas" hidden></div></div><div class="real-map-footer"><p id="map-status" role="status">Real street map · internet required. Drag to explore and use the map zoom controls.</p><div class="actions"><button class="secondary" id="fit-map">Show all visible areas</button><a id="open-area-map" class="button secondary" href="https://www.openstreetmap.org/" target="_blank" rel="noopener noreferrer">Open area in OpenStreetMap ↗</a></div><p class="meta">Map data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>. If tiles do not appear, check your internet connection or use the external map link.</p></div></div><div><div id="zone-list">${D.zones.map((z,i)=>`<button class="zone-button" data-zone="${z.id}">${i+1}. ${z.name}<small>${z.status} · ${z.impact} impact</small></button>`).join('')}</div><div class="card" id="zone-detail" aria-live="polite"></div></div></div>`;
  let selectedMapZone=selected;
  const select=(zoneId,pan=true)=>{const z=D.zones.find(z=>z.id===zoneId);document.querySelectorAll('[data-zone]').forEach(b=>{b.classList.toggle('selected',b.dataset.zone===zoneId);b.setAttribute('aria-pressed',String(b.dataset.zone===zoneId))});document.querySelector('#zone-detail').innerHTML=`${badge(z.impact+' impact',z.impact==='High'?'closure':'')}<h3>${z.name}</h3><p class="muted">${z.description}</p><p class="meta">Map marker: approximate neighbourhood centre.</p>${D.notices.filter(n=>n.zone===z.id).map(n=>`<p><a class="text-link" href="#updates/${n.id}">${esc(n.title)} →</a></p>`).join('')}<a class="button secondary" href="#feedback/${z.id}">Report a concern</a>`;selectedMapZone=z;if(activeMap)activeMap.select(z,pan)};
  activeMap=window.MutiaraMap.mount({zones:D.zones,selected,onSelect:select});
  document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>select(b.dataset.zone));document.querySelector('#fit-map').onclick=()=>activeMap.fit();select(selected.id);
  document.querySelector('#impact-filter').onchange=e=>{const impact=e.target.value,visible=D.zones.filter(z=>!impact||z.impact===impact);document.querySelectorAll('[data-zone]').forEach(button=>button.hidden=!visible.some(z=>z.id===button.dataset.zone));document.querySelector('#zone-count').textContent=visible.length+' zone'+(visible.length===1?'':'s')+' shown';if(!visible.some(z=>z.id===selectedMapZone.id))select(visible[0].id);activeMap.filter(visible)};
}
function feedback(zoneId){
  main.innerHTML=title('WE’RE LISTENING','Share your feedback','Tell us what happened so the proposed community team can understand the concern.')+`<ol class="form-steps" aria-label="Feedback submission steps"><li id="form-step-details" class="current">1 <span>Your concern</span></li><li id="form-step-review">2 <span>Review details</span></li><li id="form-step-done">3 <span>Keep reference</span></li></ol><div id="confirmation" role="status"></div><div id="feedback-review" hidden></div><div class="two"><form id="feedback-form" class="card" novalidate><div class="form-heading"><h2>Your concern matters.</h2><span class="meta">Fields marked * are required</span></div><p class="muted">Use fictional details for this academic demonstration.</p><div id="form-errors" role="alert" tabindex="-1"></div><div class="form-grid"><div class="field"><label for="name">Full name *</label><input id="name" name="name" required maxlength="80" autocomplete="name"><small class="error" id="name-error"></small></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" required maxlength="120" autocomplete="email"><small class="error" id="email-error"></small></div><div class="field"><label for="category">Concern category *</label><select id="category" name="category" required>${options(D.categories,'Select a category')}</select><small class="error" id="category-error"></small></div><div class="field"><label for="location">Affected area *</label><select id="location" name="location" required>${options([...D.areas,'Other'],'Select an area')}</select><small class="error" id="location-error"></small></div><div class="field full"><label for="landmark">Road or landmark <span class="optional">(optional)</span></label><input id="landmark" name="landmark" maxlength="160" placeholder="e.g. near the pedestrian crossing"></div><div class="field full"><label for="description">Describe your concern *</label><textarea id="description" name="description" required minlength="15" maxlength="2000" aria-describedby="description-help description-error" placeholder="What happened, where, and when?"></textarea><div class="helper-row"><small id="description-help">15–2,000 characters. Avoid sensitive personal details.</small><small id="character-count">0 / 2,000</small></div><small class="error" id="description-error"></small></div></div><label class="check" for="consent"><input id="consent" name="consent" type="checkbox" required> I understand this is a student simulation. My feedback stays in this browser and is not sent to an authority. *</label><small class="error" id="consent-error"></small><div class="actions"><button class="primary" type="submit">Review feedback →</button><button class="secondary" type="reset">Clear form</button></div></form><div><div class="callout"><h2>What happens next?</h2><ol class="next-steps"><li><b>Keep your reference</b><p>A unique number is created after your feedback is saved.</p></li><li><b>Check the record</b><p>Open the tracking page to see the concern and its timeline.</p></li><li><b>Explore the workflow</b><p>Use labelled demo controls to simulate a team response.</p></li></ol></div><div class="card" style="margin-top:18px"><h3>Before you send</h3><p class="muted">Describe one concern per submission. Include a road, time and impact where helpful.</p><p class="muted">For an urgent hazard, contact the appropriate local emergency service. This prototype is not monitored.</p></div><div class="info">Part A uses browser storage. Records do not sync between devices or browsers. No email notification is sent.</div></div></div>`;
  const formElement=document.querySelector('#feedback-form');
  if(feedbackDraft){Object.entries(feedbackDraft).forEach(([key,value])=>{const input=formElement.elements.namedItem(key);if(input&&key!=='consent')input.value=value});document.querySelector('#consent').checked=Boolean(feedbackDraft.consent);toast('Your unfinished feedback has been restored for this tab.');}
  const z=D.zones.find(z=>z.id===zoneId);if(z)document.querySelector('#location').value=z.area;
  const form=document.querySelector('#feedback-form'),description=document.querySelector('#description');description.oninput=()=>document.querySelector('#character-count').textContent=description.value.length+' / 2,000';description.oninput();
  const rememberDraft=()=>{feedbackDraft=Object.fromEntries(new FormData(form));feedbackDraft.consent=document.querySelector('#consent').checked};form.addEventListener('input',rememberDraft);form.addEventListener('change',rememberDraft);
  const clearErrors=()=>{document.querySelector('#form-errors').innerHTML='';form.querySelectorAll('.error').forEach(e=>e.textContent='');form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'))};
  form.onreset=()=>{feedbackDraft=null;clearErrors();document.querySelector('#character-count').textContent='0 / 2,000'};
  form.onsubmit=e=>{e.preventDefault();clearErrors();const data=Object.fromEntries(new FormData(form));data.consent=document.querySelector('#consent').checked;const errors=C.validate(data);if(!D.categories.includes(data.category))errors.category='Choose a concern category.';if(![...D.areas,'Other'].includes(data.location))errors.location='Choose the affected area.';
    if(Object.keys(errors).length){document.querySelector('#form-errors').innerHTML=`<div class="error-summary"><b>Please check your feedback</b><ul>${Object.entries(errors).map(([k,v])=>`<li><a href="#${k}" data-error-field="${k}">${esc(v)}</a></li>`).join('')}</ul></div>`;Object.entries(errors).forEach(([key,message])=>{const input=document.getElementById(key);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',key+'-error');document.getElementById(key+'-error').textContent=message});document.querySelectorAll('[data-error-field]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.errorField).focus()});document.querySelector('#form-errors').focus();return}
    feedbackDraft={...data};showFeedbackReview(data,form);

  };
}
function showFeedbackReview(data,form){
  form.hidden=true;document.querySelector('#form-step-details').classList.remove('current');document.querySelector('#form-step-review').classList.add('current');const panel=document.querySelector('#feedback-review');panel.hidden=false;panel.innerHTML=`<section class="card review-card" aria-labelledby="review-heading"><p class="eyebrow">CHECK BEFORE YOU SAVE</p><h2 id="review-heading" tabindex="-1">Review your feedback</h2><p class="muted">Your reference will be generated only after you confirm. Nothing has been saved yet.</p><dl class="facts"><div><dt>Name</dt><dd>${esc(data.name.trim())}</dd></div><div><dt>Email</dt><dd>${esc(data.email.trim())}</dd></div><div><dt>Category</dt><dd>${esc(data.category)}</dd></div><div><dt>Affected area</dt><dd>${esc(data.location)}</dd></div><div><dt>Road / landmark</dt><dd>${esc(data.landmark||'Not specified')}</dd></div></dl><h3>Your concern</h3><p class="preserve-lines">${esc(data.description.trim())}</p><div class="info">This academic prototype saves in this browser only. No authority receives your feedback.</div><div id="review-error" role="alert"></div><div class="actions"><button class="primary" id="confirm-feedback">Confirm & save feedback →</button><button class="secondary" id="edit-feedback">← Edit details</button></div></section>`;
  document.querySelector('#review-heading').focus();document.querySelector('#edit-feedback').onclick=()=>{panel.hidden=true;form.hidden=false;document.querySelector('#form-step-review').classList.remove('current');document.querySelector('#form-step-details').classList.add('current');document.querySelector('#name').focus()};document.querySelector('#confirm-feedback').onclick=()=>commitFeedback(data,form);
}
function commitFeedback(data,form){
  const error=message=>document.querySelector('#review-error').innerHTML=`<div class="error-summary">${esc(message)} Your details have been kept; you can retry or edit them.</div>`;
  const loaded=loadCases();if(loaded.error){error(loaded.error);return}let record;try{let id;do{id=C.reference(crypto)}while(loaded.records.some(r=>r.id===id));record=C.create(data,id)}catch{error('This browser cannot generate a secure complaint reference. Try a current browser.');return}
  const button=document.querySelector('#confirm-feedback');button.disabled=true;
  if(!persist([...loaded.records,record])){button.disabled=false;error('Your browser could not save the complaint. Enable site storage or free some space and try again.');return}
  feedbackDraft=null;form.reset();form.hidden=true;document.querySelector('#feedback-review').hidden=true;document.querySelector('#form-step-review').classList.remove('current');document.querySelector('#form-step-done').classList.add('current');document.querySelector('#confirmation').innerHTML=`<div class="success"><span class="success-tick">✓</span><h2 id="saved-heading" tabindex="-1">Feedback saved successfully.</h2><p>Your reference number</p><strong id="saved-reference">${record.id}</strong><p>Keep this number. Your record is stored only in this browser; no email is sent.</p><div class="actions"><a class="button" href="#tracking/${record.id}">Track this complaint →</a><button class="secondary" id="copy-reference">Copy reference</button><button class="secondary" id="success-receipt">Download receipt</button><button class="secondary" id="another-feedback">Submit another</button></div></div>`;document.querySelector('#copy-reference').onclick=()=>copyReference(record.id);document.querySelector('#success-receipt').onclick=()=>downloadReceipt(record);document.querySelector('#another-feedback').onclick=()=>feedback();document.querySelector('#saved-heading').focus();
}
function showSaveError(message){document.querySelector('#form-errors').innerHTML=`<div class="error-summary">${esc(message)}</div>`;document.querySelector('#form-errors').focus()}
async function copyReference(id){try{await navigator.clipboard.writeText(id);toast('Reference copied to clipboard.')}catch{toast('Copy is unavailable. Select and copy the displayed reference number.')}}
function tracking(id=''){
  const loaded=loadCases();
  main.innerHTML=title('EVERY CONCERN COUNTS','Track your complaint','Find your concern, view its history and explore the response workflow.')+`<div class="card"><form class="track-search" id="track-form"><input id="reference" aria-label="Complaint reference number" placeholder="e.g. MC-2026-DEMO01" value="${esc(id)}" required maxlength="60" autocapitalize="characters" spellcheck="false"><button class="primary">Find complaint →</button></form><div class="demo-hint"><span class="meta">Just exploring? Try a fictional case.</span><button class="secondary" id="demo-case">View sample complaint</button></div></div><div id="track-result" aria-live="polite" style="margin-top:22px"></div>${loaded.error?`<div class="info">${esc(loaded.error)}</div>`:''}<div class="section-head"><h2>Your saved complaints</h2><span class="meta">This browser only</span></div><div class="filters saved-filters"><input id="case-search" type="search" aria-label="Search saved complaints" placeholder="Search reference, concern or area…"><select id="case-status" aria-label="Filter saved complaint status"><option value="">All statuses</option>${D.stages.map((stage,i)=>`<option value="${i}">${stage}</option>`).join('')}</select></div><p class="meta" id="saved-count" role="status"></p><div id="saved-cases"></div>`;
  const find=()=>{const ref=document.querySelector('#reference').value.trim().toUpperCase();if(!ref)return;const record=ref===D.sample.id?D.sample:loadCases().records.find(r=>r.id===ref);if(!record){document.querySelector('#track-result').innerHTML='<div class="card empty"><h3>No complaint found</h3><p>Check the reference number and use the browser where you submitted it.</p><a href="#feedback" class="text-link">Submit a new concern →</a></div>';return}renderCase(record)};
  document.querySelector('#track-form').onsubmit=e=>{e.preventDefault();find()};document.querySelector('#demo-case').onclick=()=>{document.querySelector('#reference').value=D.sample.id;find()};document.querySelector('#case-search').oninput=()=>renderSavedCases(loadCases().records);document.querySelector('#case-status').onchange=()=>renderSavedCases(loadCases().records);renderSavedCases(loaded.records);if(id)find();
}
function renderSavedCases(rows){const total=rows.length,query=document.querySelector('#case-search').value,status=document.querySelector('#case-status').value;rows=C.filterCases(rows,{query,status});document.querySelector('#saved-count').textContent=`${rows.length} of ${total} saved complaints`;document.querySelector('#saved-cases').innerHTML=rows.length?`<div class="saved-list">${rows.slice().sort((a,b)=>b.created.localeCompare(a.created)).map(r=>`<a class="card saved-case" href="#tracking/${r.id}"><div><b>${esc(r.category)}</b><small>${esc(r.location)} · ${formatDate(r.created)}</small><span class="reference-label">${r.id}</span></div>${badge(D.stages[r.status])}<span aria-hidden="true">→</span></a>`).join('')}</div>`:total?'<div class="card empty"><h3>No matching complaints</h3><p>Try a different search or select All statuses.</p></div>':'<div class="card empty"><h3>No feedback saved yet</h3><p>Your submissions will appear here after you save a concern.</p><a href="#feedback" class="button secondary">Share your first concern →</a></div>'}
function renderCase(record){
  const sample=record.id===D.sample.id;
  document.querySelector('#track-result').innerHTML=`<article class="card case-card"><div class="section-head" style="margin-top:0"><div><p class="eyebrow">${sample?'FICTIONAL SAMPLE CASE':'YOUR COMPLAINT'}</p><h2 class="case-reference">${esc(record.id)}</h2></div>${badge(D.stages[record.status])}</div><div class="case-progress" aria-label="Complaint progress">${D.stages.map((s,i)=>`<span class="${i<=record.status?'complete':''}">${i+1}<small>${s}</small></span>`).join('')}</div><dl class="facts"><div><dt>Category</dt><dd>${esc(record.category)}</dd></div><div><dt>Affected area</dt><dd>${esc(record.location)}</dd></div><div><dt>Submitted</dt><dd>${formatTime(record.created)}</dd></div><div><dt>Road / landmark</dt><dd>${esc(record.landmark||'Not specified')}</dd></div></dl><h3>Your concern</h3><p class="preserve-lines">${esc(record.description)}</p><h3>Response timeline</h3><div class="timeline">${D.stages.map((s,i)=>{const h=record.history.find(h=>h.stage===i);return`<div class="step ${h?'done':''}"><b>${s}</b>${h?`<p>${esc(h.note)}</p><small>${formatTime(h.at)}</small>`:'<p>Awaiting a future update.</p>'}</div>`}).join('')}</div><div class="actions"><button class="secondary" id="copy-case">Copy reference</button><button class="secondary" id="download-receipt">Download receipt</button></div><div class="info">${sample?'This is a fictional case history.':'Your feedback is saved locally. No authority receives or processes it.'} Status changes below are for classroom demonstration only.</div>${!sample?`<section class="follow-up"><h3>Additional information</h3><div id="follow-up-list">${(record.messages||[]).map(m=>`<div class="message"><b>Your follow-up</b><p class="preserve-lines">${esc(m.text)}</p><small>${formatTime(m.at)}</small></div>`).join('')||'<p class="muted">No follow-up notes yet.</p>'}</div><form id="follow-up-form" novalidate><label for="follow-up-text">Add a clarification to this concern</label><textarea id="follow-up-text" minlength="5" maxlength="1000" aria-describedby="follow-up-error" placeholder="Add a road, time or other useful detail (5–1,000 characters)"></textarea><small id="follow-up-error" class="error" role="alert"></small><button class="secondary">Save follow-up note</button></form></section><details class="demo-panel"><summary>Demonstration controls · simulate the project team</summary><p>Advance this local record through the proposed response workflow. This is not a staff account or a real response.</p>${record.status<3?`<label for="response-note">Example response note</label><textarea id="response-note" maxlength="400" placeholder="Add a short fictional team response (optional)"></textarea><button id="advance-status" class="primary">Simulate: ${D.stages[record.status+1]} →</button>`:'<p class="resolved-message">✓ This demonstration concern has reached the final stage.</p>'}</details>`:''}</article>`;
  document.querySelector('#copy-case').onclick=()=>copyReference(record.id);
  document.querySelector('#download-receipt').onclick=()=>downloadReceipt(record);
  const followUp=document.querySelector('#follow-up-form');if(followUp)followUp.onsubmit=e=>{e.preventDefault();const input=document.querySelector('#follow-up-text'),text=input.value.trim(),error=document.querySelector('#follow-up-error');if(text.length<5||text.length>1000){error.textContent='Enter a clarification using 5–1,000 characters.';input.setAttribute('aria-invalid','true');input.focus();return}const loaded=loadCases(),current=loaded.records.find(r=>r.id===record.id);if(loaded.error||!current){error.textContent=loaded.error||'This record is no longer available.';return}const next=C.addMessage(current,text),rows=loaded.records.map(r=>r.id===record.id?next:r);if(!persist(rows)){error.textContent='Your note could not be saved. Please try again.';return}renderCase(next);toast('Follow-up information saved in this browser.')};
  const advance=document.querySelector('#advance-status');if(advance)advance.onclick=()=>{const loaded=loadCases();if(loaded.error){toast(loaded.error);return}const current=loaded.records.find(r=>r.id===record.id);if(!current){toast('This record is no longer available in this browser.');return}const next=C.advance(current,document.querySelector('#response-note').value);const rows=loaded.records.map(r=>r.id===record.id?next:r);if(!persist(rows)){toast('Status could not be saved. The previous status is unchanged.');return}renderCase(next);renderSavedCases(rows);toast('Demonstration status updated to '+D.stages[next.status]+'.')};
}
function downloadReceipt(r){const lines=['MUTIARA CONNECT — ACADEMIC SIMULATION','Feedback receipt (stored in this browser only)','',`Reference: ${r.id}`,`Status: ${D.stages[r.status]}`,`Submitted: ${formatTime(r.created)}`,`Category: ${r.category}`,`Area: ${r.location}`,`Landmark: ${r.landmark||'Not specified'}`,'','Concern:',r.description,'','Timeline:',...r.history.map(h=>`${D.stages[h.stage]} | ${formatTime(h.at)}\n${h.note}`),'','Additional information:',...(r.messages||[]).map(m=>formatTime(m.at)+'\n'+m.text),'','This is not an official complaint or authority response.'];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=r.id+'-receipt.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Receipt download requested.')}
function about(){main.innerHTML=title('ABOUT THIS PROTOTYPE','A clearer channel for the community.','CMT322 Web Engineering & Technologies · Part A working simulation')+`<div class="two"><div class="card"><h2>Scope & architecture</h2><p>Mutiara Connect implements five connected modules: project information, construction updates, a work-zone map, feedback submission and complaint tracking.</p><p>The Part A implementation uses semantic HTML, responsive CSS and plain JavaScript. Feedback and simulated status updates are stored in this browser using localStorage. A future Part B implementation would move records to a server database, authenticate project staff and provide genuine notifications.</p><h3>Data & privacy</h3><p>No feedback is sent to a project authority. Records remain in the browser profile where they are created and may be lost if site data is cleared. Use fictional names and emails during demonstrations.</p><h3>Map information</h3><p>The main map uses real OpenStreetMap streets and geography. Leaflet provides interactive markers, zoom and panning, with a real embedded street map as fallback. Markers show approximate neighbourhood centres, not official construction sites or boundaries.</p><h3>Content source</h3><p>The project introduction is informed by the <a class="text-link" href="https://laluanmutiara.mymrt.com.my/lrt-mutiara-line/" target="_blank" rel="noopener noreferrer">official MRT Corp Mutiara Line project page ↗</a>, checked 2 November 2026. All work notices, dates, diversions and case responses are created for this academic simulation.</p></div><div class="callout"><h2>AI assistance disclosure</h2><p>OpenAI ChatGPT / Codex was used to assist with interface design, HTML, CSS and JavaScript implementation, sample content and automated logic checks.</p><p>The student team is responsible for reviewing, understanding, modifying and validating the final submission. AI assistance should be acknowledged in the project report in accordance with the lecturer’s guidance.</p><h3>Recording your demonstration</h3><p>Use your team’s own faces and voices. Follow the course requirements for the recorded simulation.</p><a href="#home" class="button">Explore the prototype →</a></div></div>`}
function notFound(h,p,href='#home',label='Return home'){main.innerHTML=title('LET’S GET YOU BACK',h,p)+`<a class="button" href="${href}">${label} →</a>`}
let firstRoute=true;
function route(){if(activeMap){activeMap.destroy();activeMap=null}const raw=location.hash.slice(1);const [page='home',arg]=raw.split('/');const key=page||'home';document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+key;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const routes={home,updates,map,feedback,tracking,about};if(routes[key])routes[key](arg);else notFound('Page not found','Use the navigation to explore the community portal.');document.title=({home:'Home & Project',updates:'Construction Updates',map:'Construction Map',feedback:'Submit Feedback',tracking:'Complaint Tracking',about:'About & AI Disclosure'}[key]||'Page Not Found')+' | Mutiara Connect';document.querySelector('#current-page').textContent=({home:'Home & Project',updates:arg?'Notice details':'Construction Updates',map:'Construction Map',feedback:'Submit Feedback',tracking:'Complaint Tracking',about:'About & disclosure'}[key]||'Page not found');window.scrollTo(0,0);if(!firstRoute)main.focus({preventScroll:true});firstRoute=false;}
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key===C.KEY&&location.hash.startsWith('#tracking')){const ref=document.querySelector('#reference')?.value||'';tracking(ref)}});
route();
